template:
use std::cell::OnceCell;

struct Buffer {
    raw: OnceCell<Vec<u8>>,
}

impl Buffer {
    fn bytes(&self) -> &[u8] {
        self.raw.⟦slot1⟧(|| ⟦slot2⟧)
    }
}

fn main() {
    let b = Buffer {
        raw: OnceCell::new(),
    };
    println!("{:?}", b.bytes());
}

tests:
#[test]
fn initializes_once() {
    let b = Buffer { raw: OnceCell::new() };
    assert_eq!(b.bytes(), &[1, 2, 3]);
    assert_eq!(b.bytes(), &[1, 2, 3]);
}
